// ブラジル天球儀（青い地球＋白い帯＋ORDEM E PROGRESSO文字＋27個の星）描画ヘルパー
const renderBrazilGlobe = (uid: string, globeColor: string) => (
  <>
    <defs>
      <path id={`br_text_arc_${uid}`} d="M 101 89.5 A 123.5 123.5 0 0 1 200 118" fill="none" />
    </defs>
    <circle cx="150" cy="105" r="52.5" fill={globeColor} />
    <path d={BR_BAND_PATH} fill="#ffffff" />
    <text
      fill="#009b3a"
      fontSize="5.8"
      fontWeight="900"
      fontFamily="sans-serif"
      letterSpacing="0.3"
    >
      <textPath href={`#br_text_arc_${uid}`} startOffset="50%" textAnchor="middle">
        ORDEM E PROGRESSO
      </textPath>
    </text>
    <path d={BR_STARS_PATH} fill="#ffffff" />
  </>
);

